import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int n = Integer.parseInt(st.nextToken());
        // Two digit strings are rotations of each other iff their smallest rotations match.
        HashMap<String, Integer> count = new HashMap<>(2 * n + 1);
        long ans = 0;
        for (int i = 0; i < n; i++) {
            String s = st.nextToken(), best = s;
            for (int k = 1; k < s.length(); k++) {
                String t = s.substring(k) + s.substring(0, k);
                if (t.compareTo(best) < 0) best = t;
            }
            int c = count.getOrDefault(best, 0);
            ans += c;
            count.put(best, c + 1);
        }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	sc.Scan()
	n, _ := strconv.Atoi(sc.Text())
	// Two digit strings are rotations of each other iff their smallest rotations match.
	count := make(map[string]int64, 2*n)
	var ans int64
	for i := 0; i < n; i++ {
		sc.Scan()
		s := sc.Text()
		best := s
		for k := 1; k < len(s); k++ {
			if t := s[k:] + s[:k]; t < best {
				best = t
			}
		}
		ans += count[best]
		count[best]++
	}
	fmt.Println(ans)
}
